import fs from'node:fs';import assert from'node:assert/strict';import{pathToFileURL}from'node:url';import{createHash}from'node:crypto';import{execFileSync}from'node:child_process';
const atlas='F:/VisibleMedicine/staging/20261027-oral-recall-native/atlas';assert.equal(process.cwd().replaceAll('\\','/'),atlas);
const git=(...args)=>execFileSync('git',args,{encoding:'utf8',windowsHide:true}).trim(),parent='d5c86abea551c92a4e59be57059e6b652fa01bde';assert.equal(git('rev-parse','HEAD'),parent);
const sha=bytes=>createHash('sha256').update(bytes).digest('hex');assert.equal(sha(fs.readFileSync('app/body-content.ts')),sha(execFileSync('git',['show',parent+':app/body-content.ts'],{windowsHide:true})));
const{contentContext}=await import(pathToFileURL(atlas+'/scripts/content-contract-tools.mjs'));const{api,catalog}=await contentContext(),display=api.bodyDisplayCatalog(catalog);
const pending=display.structures.filter(s=>s.region==='head-neck'&&api.bodyLesson(s,'quiz').readiness==='generated-identification');assert.equal(pending.length,30);
function group(s){if(s.fmaId==='FMA54640')return'tongue';if(s.fmaId==='FMA46733')return'uvula';for(const[g,re]of [['incisors',/secondary-incisor-tooth$/],['canines',/secondary-canine-tooth$/],['premolars',/secondary-premolar-tooth$/],['molars',/secondary-molar-tooth$/]])if(re.test(s.id))return g;throw Error('Unclassified pending source '+s.id);}
const entries=pending.map(identity=>({identity,group:group(identity),previous:api.bodyLesson(identity,'quiz')}));const counts=Object.fromEntries(['incisors','canines','premolars','molars','tongue','uvula'].map(g=>[g,entries.filter(e=>e.group===g).length]));assert.deepEqual(counts,{incisors:8,canines:4,premolars:8,molars:8,tongue:1,uvula:1});
const bundleIds=new Set(entries.map(e=>e.identity.bundle)),bundles=display.bundles.filter(b=>bundleIds.has(b.id));assert.equal(bundles.length,bundleIds.size);for(const b of bundles){const bytes=fs.readFileSync('public'+b.url.split('?')[0]);assert.equal(bytes.length,b.bytes);assert.equal(sha(bytes),b.sha256);}
const pins={parentCommit:parent,catalogHash:sha(JSON.stringify(display)),coordinateSystem:display.coordinateSystem,bundles,entries};fs.writeFileSync('content/oral-recall-quiz-pins.json',JSON.stringify(pins,null,2)+'\n',{flag:'wx'});
fs.writeFileSync('../PIN_RECEIPT.json',JSON.stringify({at:new Date().toISOString(),parentCommit:parent,rootCatalogHash:pins.catalogHash,entries:entries.length,groups:counts,bundles:bundles.length,pinsSha256:sha(JSON.stringify(pins)),pinFileSha256:sha(fs.readFileSync('content/oral-recall-quiz-pins.json')),noClinicalApproval:true,publicGeometryUnchanged:true},null,2)+'\n',{flag:'wx'});console.log(JSON.stringify({entries:entries.length,groups:counts,pinsSha256:sha(JSON.stringify(pins)),bundles:bundles.length}));
